"""Deep-research engine v3 — a linear control plane over bounded agentic gathering.

WHY THIS FILE WAS REWRITTEN (condensed forensics, see V3_SPEC §0)
-------------------------------------------------------------------
* The legacy LangGraph loop sent 46.8M prompt tokens for one question
  (18:1 prompt/output), replayed from zero after every crash and never
  converged on its fail-closed judge.
* The v2 file this replaces never completed a fresh run: prompts containing
  literal JSON were passed through ``str.format`` (KeyError), every fetch
  called an async-only tool synchronously (TypeError), synthesis emitted
  sections out of order, References dumped the whole ledger, instructions
  were wrapped as "untrusted evidence", no ``[usage]`` lines were emitted,
  parameters were passed by mutating ``os.environ`` and notes were written
  after KIQs were marked done (a resume lost the evidence).

DESIGN
------
Six phases run strictly in order; each persists its artifacts under
``out_dir/v3`` atomically BEFORE it (or a unit inside it) is marked done, so a
resumed attempt skips finished work and never re-pays for it:

1. **plan** — scope call, concurrent scout searches, plan call; deterministic
   normalisation (engine-assigned KIQ ids, clamped outline, one canonical
   scenario frame with integer weights summing to 100) and a deterministic
   fallback plan when the model cannot deliver one.
2. **gather** — one bounded tool-using agent per KIQ (append-only local
   context, step/novelty/budget/deadline stops, forced final notes), fanned
   out after one cache-priming call.
3. **gap** — optional follow-up rounds chosen from a deterministic coverage
   matrix.
4. **synthesize** — contiguous section groups written in parallel over one
   byte-identical evidence digest, re-assembled in outline order; the
   executive summary is written last from the section leads.
5. **qa** — deterministic checks and bounded, section-scoped repairs; the
   citation namespace becomes positional ``[S1..Sk]`` and References are
   generated by code from cited sources only.
6. **finalize** — the contract artifacts (report, sources, actors, timeline,
   quantitative, contested), analytics, prediction markets and charts.

Every LLM call goes through :mod:`research_gateway` (usage lines, cost ledger,
retries, fallback model, budget checked before paying) with the cache-friendly
layout ``[ENGINE_CORE][RUN BRIEF][shared context...][task]``: everything
volatile lives only in the LAST message, and tool-using conversations are
append-only with the same tools object bound on every call.

Contract with ``deerflow_research.main``: ``run`` never closes ``plog`` (main
owns it), never mutates ``os.environ`` (the one exception: the production
model factory caps this child process's cross-process lease wait and bounds
it by each call's deadline, see :func:`_bridge_lease`), never writes outside
``out_dir`` and always leaves ``meta.status`` terminal (a SIGTERM ends the run
as ``failed``/``terminated``).  Exit 0 iff research_report.md (>= 400 chars)
was written; 2 otherwise (resumable), which includes a run the provider never
answered (see ``_Engine._require_model_output``).
"""

