def _render(template: string.Template, **fields: Any) -> str:
    """Substitute a prompt template; a missing field raises (a caller bug)."""
    return template.substitute({key: str(value) for key, value in fields.items()})


# ===========================================================================
# Small pure helpers
# ===========================================================================

def _iso_now() -> str:
    return _dt.datetime.now(_dt.timezone.utc).isoformat()


def _utc_date() -> str:
    return _dt.datetime.now(_dt.timezone.utc).date().isoformat()


def _canonical_date(value: Any) -> bool:
    """True for the exact canonical ``YYYY-MM-DD`` spelling of a real calendar date.

    The rule of the backend's ``utils.point_in_time.validate_as_of`` (this child cannot
    import the backend): a string that survives a strptime/strftime round trip, so
    '2024-6-1', '2024-06-01 00:00' and '2024-02-30' are refused.
    """
    if not isinstance(value, str):
        return False
    try:
        return _dt.datetime.strptime(value, "%Y-%m-%d").strftime("%Y-%m-%d") == value
    except ValueError:
        return False


def _hindcast_as_of(env: Mapping[str, Any] | None) -> str | None:
    """RESEARCH_AS_OF of the run env when it pins a canonical date before today (UTC), else None.

    Such a run is a hindcast: its prompts carry the point-in-time rule and fetched pages
    are labelled as live.  A pin equal to today is live; the engine refuses an invalid
    or future value before this matters (:class:`_Engine`).
    """
    raw = str((env or {}).get("RESEARCH_AS_OF", "") or "").strip()
    if not _canonical_date(raw):
        return None
    return raw if _dt.date.fromisoformat(raw) < _dt.date.fromisoformat(_utc_date()) else None


def _compact_utc() -> str:
    return _dt.datetime.now(_dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")


def _sha256(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def _collapse(value: Any, limit: int = 0) -> str:
    """Single-line, whitespace-collapsed text, optionally capped with an ellipsis."""
    text = " ".join(str(value or "").split())
    if limit and len(text) > limit:
        cut = text[: max(1, limit - 1)]
        space = cut.rfind(" ")
        if space > limit * 0.6:
            cut = cut[:space]
        text = cut.rstrip(" ,;:") + "…"
    return text


def _norm_key(value: Any) -> str:
    """Dedup key: NFKC, casefold, letters/digits (incl. CJK) only."""
    text = unicodedata.normalize("NFKC", str(value or "")).casefold()
    return re.sub(r"[\W_]+", "", text)


def _name_key(name: Any) -> str:
    """Mirror of backend ``app.utils.actors.normalize_name`` (scenario/actor identity)."""
    text = unicodedata.normalize("NFKC", str(name or "")).lower()
    return re.sub(r"[\s\.\,\:\;\-\_\(\)\[\]【】（）'\"·]+", "", text)


def _natural_key(kid: str) -> tuple:
    """K1 < K2 < K10, then G1F1 < G1F2 < G2F1 (plan KIQs before follow-ups)."""
    parts = [int(tok) if tok.isdigit() else tok for tok in re.split(r"(\d+)", kid) if tok]
    return (0 if kid.startswith("K") else 1, parts)


def _as_str_list(value: Any, *, limit: int = 0, item_chars: int = 300) -> list[str]:
    if isinstance(value, str):
        value = [value]
    if not isinstance(value, (list, tuple)):
        return []
    out: list[str] = []
    seen: set[str] = set()
    for item in value:
        if isinstance(item, (dict, list, tuple)) or item is None:
            continue
        text = _collapse(item, item_chars)
        key = _norm_key(text)
        if text and key and key not in seen:
            seen.add(key)
            out.append(text)
        if limit and len(out) >= limit:
            break
    return out


def _read_json(path: Path) -> Any:
    try:
        return json.loads(path.read_text("utf-8"))
    except (OSError, ValueError):
        return None


def _read_text(path: Path) -> str | None:
    try:
        return path.read_text("utf-8")
    except OSError:
        return None


